+<!doctype html>
+<html lang="en">
+<head>
+  <meta charset="utf-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <title>Keep — Save a bookmark</title>
+  <style>
+    :root { color-scheme: light; --ink:#17201d; --muted:#68736e; --line:#dfe6e2; --paper:#fff; --wash:#f3f6f3; --green:#28664f; --green2:#e5f1eb; }
+    * { box-sizing: border-box; }
+    body { margin:0; min-height:100vh; background:var(--wash); color:var(--ink); font:15px/1.5 Inter, ui-sans-serif, system-ui, sans-serif; }
+    header { height:68px; background:var(--paper); border-bottom:1px solid var(--line); display:flex; align-items:center; padding:0 5vw; }
+    .brand { font:700 21px/1.2 Georgia, serif; letter-spacing:.01em; }
+    .brand i { display:inline-block; width:11px; height:15px; margin-right:9px; background:var(--green); border-radius:2px 2px 5px 5px; vertical-align:-2px; }
+    main { width:min(760px, 90vw); margin:72px auto; }
+    .eyebrow { color:var(--green); font-weight:700; letter-spacing:.1em; text-transform:uppercase; font-size:12px; }
+    h1 { font:600 clamp(34px, 5vw, 52px)/1.08 Georgia, serif; margin:12px 0 12px; letter-spacing:-.025em; }
+    .lede { color:var(--muted); font-size:17px; margin:0 0 32px; }
+    .panel { background:var(--paper); border:1px solid var(--line); border-radius:18px; padding:24px; box-shadow:0 18px 48px rgba(25,48,39,.07); }
+    label { display:block; font-weight:700; margin-bottom:8px; }
+    .urlrow { display:flex; gap:10px; }
+    input { width:100%; height:48px; border:1px solid #c8d2cd; border-radius:10px; padding:0 14px; font:inherit; color:var(--ink); outline:none; }
+    input:focus { border-color:var(--green); box-shadow:0 0 0 3px var(--green2); }
+    button { border:0; border-radius:10px; padding:0 20px; font:700 15px/1 system-ui,sans-serif; cursor:pointer; }
+    .primary { height:48px; color:white; background:var(--green); min-width:142px; }
+    .primary:hover { background:#1f5641; }
+    .hint { color:var(--muted); font-size:13px; margin:9px 0 0; }
+    .preview { display:none; margin-top:22px; padding-top:22px; border-top:1px solid var(--line); }
+    .preview.show { display:block; }
+    .meta { font-size:12px; color:var(--green); font-weight:700; margin-bottom:5px; }
+    .title { font:600 22px/1.25 Georgia,serif; margin:0 0 7px; }
+    .desc { color:var(--muted); margin:0; }
+    .actions { display:flex; justify-content:flex-end; gap:10px; margin-top:22px; }
+    .ghost { height:42px; background:transparent; color:var(--muted); }
+    .save { height:42px; background:var(--green); color:white; }
+    .success { display:none; align-items:center; gap:13px; }
+    .success.show { display:flex; }
+    .check { width:38px; height:38px; border-radius:50%; background:var(--green2); color:var(--green); display:grid; place-items:center; font-size:21px; font-weight:800; }
+    .success strong { display:block; }
+    .success span { color:var(--muted); font-size:13px; }
+    @media (max-width:560px) { main { margin-top:42px; } .urlrow { flex-direction:column; } .primary { width:100%; } }
+  </style>
+</head>
+<body>
+  <header><div class="brand"><i></i>Keep</div></header>
+  <main data-harness-ready="true">
+    <div class="eyebrow">Your library</div>
+    <h1>Save something worth finding again.</h1>
+    <p class="lede">Paste a link and its details will be filled in for you.</p>
+    <section class="panel" aria-live="polite">
+      <div id="form">
+        <label for="url">Web address</label>
+        <div class="urlrow">
+          <input id="url" type="url" placeholder="https://example.com/article" autocomplete="off">
+          <button class="primary" id="fetch">Get details</button>
+        </div>
+        <p class="hint">For this prototype, any complete web address will show an example preview.</p>
+        <div class="preview" id="preview">
+          <div class="meta" id="domain">THE MARGINALIAN</div>
+          <h2 class="title">How to live with presence in an age of productivity</h2>
+          <p class="desc">A thoughtful reflection on attention, purpose, and the quiet work of being fully alive.</p>
+          <div class="actions">
+            <button class="ghost" id="cancel">Cancel</button>
+            <button class="save" id="save">Save bookmark</button>
+          </div>
+        </div>
+      </div>
+      <div class="success" id="success">
+        <div class="check">✓</div>
+        <div><strong>Bookmark saved</strong><span>The title and description are now in your library.</span></div>
+      </div>
+    </section>
+  </main>
+  <script>
+    const url = document.querySelector('#url');
+    const preview = document.querySelector('#preview');
+    const form = document.querySelector('#form');
+    const success = document.querySelector('#success');
+    const domain = document.querySelector('#domain');
+    document.querySelector('#fetch').addEventListener('click', () => {
+      if (!url.value.trim()) { url.focus(); return; }
+      try { domain.textContent = new URL(url.value).hostname.replace(/^www\./,'').toUpperCase(); } catch { domain.textContent = 'SAVED PAGE'; }
+      preview.classList.add('show');
+    });
+    document.querySelector('#cancel').addEventListener('click', () => preview.classList.remove('show'));
+    document.querySelector('#save').addEventListener('click', () => { form.style.display='none'; success.classList.add('show'); });
+  </script>
+</body>
+</html>
