*** Add File: /work/package.json
+{
+  "name": "keepsake-bookmarks",
+  "version": "1.0.0",
+  "private": true,
+  "type": "module",
+  "scripts": {
+    "start": "node implementation/server.mjs",
+    "test": "node --test implementation/tests/*.test.mjs"
+  },
+  "engines": { "node": ">=24" }
+}
*** Add File: /work/implementation/store.mjs
+import { mkdir, readFile, writeFile } from 'node:fs/promises';
+import path from 'node:path';
+import { randomUUID } from 'node:crypto';
+
+export function normalizeUrl(raw) {
+  const url = new URL(raw);
+  if (!['http:', 'https:'].includes(url.protocol)) throw new Error('Only HTTP and HTTPS addresses are supported');
+  url.hash = '';
+  for (const key of [...url.searchParams.keys()]) {
+    if (/^(utm_|fbclid$|gclid$|mc_cid$|mc_eid$)/i.test(key)) url.searchParams.delete(key);
+  }
+  url.hostname = url.hostname.toLowerCase();
+  if (url.pathname !== '/') url.pathname = url.pathname.replace(/\/+$/, '');
+  url.searchParams.sort();
+  return url.toString();
+}
+
+export function comparableTag(value) {
+  return value.trim().toLocaleLowerCase().replace(/s$/, '');
+}
