  catch(error){ if(error.data?.manual){ $('#fetch-error').hidden=false; showBookmarkForm({url,title:'',description:'',siteName:new URL(url).hostname,favicon:'',thumbnail:''},true); } else $('#url-error').textContent=error.message; }
});
