const { chromium } = require('playwright');
const assert = require('node:assert/strict');
const base = process.env.APP_URL || 'http://127.0.0.1:4101';

async function api(path, options={}) { const response=await fetch(base+path,{...options,headers:{'content-type':'application/json'}}); const data=await response.json(); assert.ok(response.ok,JSON.stringify(data)); return data; }
async function create(item){ return (await api('/api/bookmarks',{method:'POST',body:JSON.stringify(item)})).bookmark; }
const item=(url,title,tags=[],extra={})=>({url,title,description:`Description for ${title}`,noteHtml:`<strong>Note:</strong> ${title} reminder`,tags,siteName:new URL(url).hostname,...extra});

(async()=>{
  const browser=await chromium.launch({headless:true}); const page=await browser.newPage({viewport:{width:1280,height:900}});
  await page.goto(base); await page.locator('[data-harness-ready="true"]').waitFor();
  // SCN-011 brand-new empty state.
  assert.equal(await page.getByText('Your library is ready').isVisible(),true); assert.equal(await page.locator('#search').isVisible(),false);
  // SCN-010 invalid address and SCN-001 fetched/editable save with note and tags.
  await page.getByRole('button',{name:'Save your first link'}).click(); await page.locator('#url').fill('not an address'); await page.locator('#url-form').getByRole('button',{name:'Get details'}).click(); assert.match(await page.locator('#url-error').innerText(),/complete web address/);
  await page.locator('#url').fill(base+'/fixture.html'); await page.locator('#url-form').getByRole('button',{name:'Get details'}).click(); await page.locator('#bookmark-form').waitFor(); assert.match(await page.locator('#bookmark-title').inputValue(),/clunky fixture/); assert.equal(await page.locator('#preview-image').isVisible(),true);
  await page.locator('#bookmark-title').fill('My saved fixture'); await page.locator('#bookmark-description').fill('My own description'); await page.locator('#bookmark-note').evaluate(el=>el.innerHTML='<strong>Remember:</strong><ul><li>Weekend plan</li></ul>'); for(const tag of ['Recipes','Research']){ await page.locator('#tag-input').fill(tag); await page.locator('#tag-input').press('Enter'); } await page.locator('#save-button').click(); await page.locator('.card').waitFor(); assert.equal(await page.locator('.card h2').innerText(),'My saved fixture'); assert.equal(await page.locator('.card .chip').count(),2); assert.equal(await page.locator('.card .note-preview li').innerText(),'Weekend plan');
  // SCN-002 active duplicate normalization and SCN-015 original-page link.
  assert.equal(await page.locator('.card h2 a').getAttribute('href'),base+'/fixture.html'); await page.locator('#new-bookmark').click(); await page.locator('#url').fill(base+'/fixture.html/?utm_source=test#section'); await page.locator('#url-form').getByRole('button',{name:'Get details'}).click(); assert.match(await page.locator('#duplicate-note').innerText(),/already in your library/); await page.getByRole('button',{name:'Close'}).click();
  const work=await create(item('https://example.com/work','A practical guide to focused work',['Work','Reading'],{readLater:true})); const presence=await create(item('https://example.com/presence','How to live with presence',['Reading'])); await page.reload(); await page.locator('[data-harness-ready="true"]').waitFor();
  // SCN-003, 004, 016 search, tag filter, and ordering together.
  await page.locator('#search').fill('WEEKEND'); assert.equal(await page.locator('.card:visible h2').innerText(),'My saved fixture'); await page.locator('#search').fill(''); await page.getByRole('button',{name:'Reading',exact:true}).click(); assert.equal(await page.locator('.card:visible').count(),2); await page.locator('#sort').selectOption('title'); assert.deepEqual(await page.locator('.card:visible h2').allInnerTexts(),['A practical guide to focused work','How to live with presence']); await page.getByRole('button',{name:'All tags',exact:true}).click();
  // SCN-006 read later and immediate removal.
  await page.locator('[data-view="later"]').click(); assert.equal(await page.locator('.card:visible h2').innerText(),work.title); await page.locator('.card:visible [data-later]').click(); await page.locator('#empty.show').waitFor(); assert.match(await page.locator('#empty').innerText(),/Nothing saved for later/); await page.locator('[data-view="active"]').click();
  // SCN-008 archive and restore preserving content.
  const presenceCard=()=>page.locator('.card').filter({has:page.getByRole('link',{name:presence.title,exact:true})}); await presenceCard().locator('[data-archive]').click(); await page.waitForFunction(()=>document.querySelector('#archive-count').textContent==='1'); await page.locator('[data-view="archive"]').click(); assert.match(await presenceCard().innerText(),/Reading/); await presenceCard().locator('[data-restore]').click(); await page.waitForFunction(()=>document.querySelector('#archive-count').textContent==='0');
  // SCN-013 explicit refresh previews without silently changing saved title.
  await page.locator('[data-view="active"]').click(); await page.locator('.card').filter({has:page.getByRole('link',{name:'My saved fixture'})}).locator('[data-edit]').click(); await page.locator('#refresh-details').click(); await page.locator('#refresh-box:not([hidden])').waitFor(); assert.equal(await page.locator('#bookmark-title').inputValue(),'My saved fixture'); await page.getByRole('button',{name:'Keep my saved details'}).click(); await page.getByRole('button',{name:'Close'}).click();
  // SCN-014 archived duplicate restores the existing item.
  const fixtureCard=()=>page.locator('.card').filter({has:page.getByRole('link',{name:'My saved fixture',exact:true})}); await fixtureCard().locator('[data-archive]').click(); await page.locator('#new-bookmark').click(); await page.locator('#url').fill(base+'/fixture.html#again'); await page.locator('#url-form').getByRole('button',{name:'Get details'}).click(); assert.match(await page.locator('#duplicate-note').innerText(),/Archive/); await page.locator('#bookmark-title').fill('Restored fixture'); await page.locator('#restore-existing').click(); await page.waitForFunction(()=>document.querySelector('#archive-count').textContent==='0'); assert.equal(await page.getByRole('link',{name:'Restored fixture'}).isVisible(),true);
  // SCN-017 bulk tagging preserves tags, later/done, archive, and guarded delete.
  const select=async title=>page.locator('.card').filter({has:page.getByRole('link',{name:title,exact:true})}).locator('.pick').check(); await select('Restored fixture'); await select(presence.title); await page.locator('[data-bulk="tag"]').click(); await page.locator('#bulk-tag-input').fill('Work'); await page.locator('#apply-bulk-tag').click(); await page.waitForFunction(()=>!document.querySelector('#bulk-bar').classList.contains('show')); assert.match(await page.locator('.card').filter({has:page.getByRole('link',{name:'Restored fixture'})}).innerText(),/Recipes[\s\S]*Work/);
  await select('Restored fixture'); await select(presence.title); await page.locator('[data-bulk="later"]').click(); await page.waitForFunction(()=>document.querySelector('#later-count').textContent==='2'); await page.locator('[data-view="later"]').click(); await select('Restored fixture'); await select(presence.title); assert.equal(await page.locator('[data-bulk="later"]').innerText(),'Mark done'); await page.locator('[data-bulk="later"]').click(); await page.locator('#empty.show').waitFor();
  await page.locator('[data-view="active"]').click(); await select('Restored fixture'); await select(presence.title); await page.locator('[data-bulk="archive"]').click(); await page.waitForFunction(()=>document.querySelector('#archive-count').textContent==='2'); await page.locator('[data-view="archive"]').click(); await select('Restored fixture'); await select(presence.title); await page.locator('[data-bulk="delete"]').click(); assert.match(await page.locator('#confirm-heading').innerText(),/2 bookmarks/); await page.getByRole('button',{name:'Cancel',exact:true}).click(); assert.equal(await page.locator('.card:visible').count(),2); await page.locator('[data-bulk="delete"]').click(); await page.locator('#confirm-delete').click(); await page.locator('#empty.show').waitFor(); assert.match(await page.locator('#empty').innerText(),/archive is empty/i);
  console.log('All integrated approved-scenario flows passed.'); await browser.close();
})().catch(error=>{ console.error(error); process.exitCode=1; });

